/** Die vier Symbolgroessen. Andere Werte gibt es nicht. */
object PocketIconSize {
    /** Marker in Metatext: Pin oder Schloss neben einem Titel, Status-Pillen. */
    val Marker = 14.dp
    /** In Buttons, Chips und Nachrichten-Aktionen. */
    val Small = 18.dp
    /** Standard: Kopfzeile, IconButton, Menue, Drawer, Eingabezeile. */
    val Regular = 24.dp
    /** Leere Zustaende und grosse Hinweisflaechen. */
    val Hero = 48.dp
}

private fun symbol(name: String, autoMirror: Boolean, pathData: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
        autoMirror = autoMirror,
    )
        // Material Symbols zeichnen in einem Raster von y = -960 bis 0.
        .addGroup(translationY = 960f)
        .addPath(pathData = addPathNodes(pathData), fill = SolidColor(Color.Black))
